INSERT INTO changelog (title, body, created_at) VALUES ('Стратегія клієнта — компактно', 'Клієнт → Стратегія → Огляд: три плитки зверху — Головне зараз, Де ми, Куди йдемо (по 3–4 рядки, клік — повністю і правка тут же, можна надиктувати). Далі плитки Цей тиждень, Цей місяць, Останнє зроблене, Висновки — деталі у віконці. Частини екосистеми — картками з логотипами сервісів, з яких складаються. Огляд стратегії тепер влазить в один екран.', datetime('now'));
